<script setup lang="ts">
import { computed, ref } from 'vue';
import { ElButton, ElCheckbox, ElCheckboxGroup, ElInput, ElOption, ElSelect, ElTag } from 'element-plus';
import { l, statusTitle } from './copy';
import { useFullReviewState } from './state';
const s=useFullReviewState();const query=ref('');const validation=ref('');
const form=computed(()=>s.draft('tenant-create',{name:'',code:'',owner:''}));
const grant=computed(()=>s.draft('module-grant',{modules:[] as string[],mode:'enabled',expiresAt:'',quota:'unlimited'}));
const rows=computed(()=>s.scene==='empty'?[]:s.data.tenants.filter(x=>(x.name+x.code).toLowerCase().includes(query.value.toLowerCase())));
const ownerInvitation=computed(()=>s.data.invites.find(x=>x.tenantId===target.value?.id&&x.role==='owner'&&x.state==='created'&&Date.parse(x.expiresAt)>Date.now()));
const nomination=computed(()=>s.draft(`nomination-${s.query.target}`,{owner:''}));
function nominate(){if(target.value)s.request(['重新指定首次企业负责人','Renew initial owner nomination'],{kind:'nominate',ids:[target.value.id],values:{name:target.value.name,owner:nomination.value.owner,version:String(target.value.version)}},'platform');}
const target=computed(()=>s.query.target?s.data.tenants.find(x=>x.id===s.query.target):s.data.tenants[0]);
function create(){validation.value='';if(!form.value.name.trim()||!/^[a-z][a-z0-9-]{2,31}$/.test(form.value.code)||!/^[^@\s]+@example\.test$/.test(form.value.owner)){validation.value=l('请填写名称、3–32位小写唯一标识及受控测试负责人地址。','Enter a name, 3–32 character lowercase code, and controlled owner email.');return;}s.request(['创建企业并指定负责人','Create organization and nominate owner'],{kind:'tenant',ids:[form.value.code],values:{name:form.value.name,code:form.value.code,owner:form.value.owner}},'platform');}
function enable(){if(!target.value)return;if(!grant.value.modules.length){validation.value=l('请先选择已发布模块。','Select a published module.');return;}s.request(['核对模块开通影响','Review module activation'],{kind:'module',ids:[...grant.value.modules],values:{tenant:target.value?.id || '',name:target.value?.name || '',version:String(target.value?.version),state:grant.value.mode,expiresAt:grant.value.expiresAt,quota:grant.value.quota}},'platform');}
</script>
<template>
  <div class="full-stack">
    <section v-if="s.page.id==='tenants'" class="full-card"><div class="full-toolbar"><ElInput v-model="query" clearable :placeholder="l('搜索企业名称或标识','Search organization name or code')" :aria-label="l('搜索企业','Search organizations')" /><ElButton type="primary" data-primary @click="s.go('tenant-create')">{{ l('创建企业','Create organization') }}</ElButton></div><div class="full-table-wrap"><table class="full-table"><thead><tr><th>{{ l('企业','Organization') }}</th><th>{{ l('唯一标识','Unique code') }}</th><th>{{ l('负责人建立状态','Owner activation') }}</th><th>{{ l('模块','Modules') }}</th><th>{{ l('操作','Action') }}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.name }}</td><td>{{ row.code }}</td><td>{{ row.state==='pending_owner'?l('等待受邀负责人验证','Awaiting nominated owner verification'):statusTitle('active') }}</td><td>{{ row.modules.join(' · ') || l('未开通商业模块','No business modules enabled') }}</td><td><ElButton link type="primary" @click="s.go('tenant',{target:row.id})">{{ l('查看企业','View organization') }}</ElButton></td></tr></tbody></table></div><p v-if="!rows.length" class="full-empty">{{ l('没有符合条件的企业','No matching organizations') }}</p><p class="full-muted">{{ l('平台管理权不等于企业成员或负责人权限。','Platform administration does not grant organization membership or ownership.') }}</p></section>
    <section v-else-if="s.page.id==='tenant-create'" class="full-card"><h2>{{ l('建立企业与负责人邀请','Create an organization and owner invitation') }}</h2><div class="full-form"><label>{{ l('企业名称','Organization name') }}<ElInput v-model="form.name" :aria-label="l('企业名称','Organization name')" maxlength="80" /></label><label>{{ l('唯一标识','Unique code') }}<ElInput v-model="form.code" :aria-label="l('企业唯一标识','Organization unique code')" maxlength="32" /><small>{{ l('小写字母开头，3–32位字母、数字或短横线。','Start with a lowercase letter; 3–32 lowercase letters, digits, or hyphens.') }}</small></label><label>{{ l('指定负责人组织账号','Nominated owner account') }}<ElInput v-model="form.owner" :aria-label="l('负责人受控测试地址','Controlled owner email')" /><small>{{ l('审阅仅接受 example.test 测试地址。负责人需验证受邀账号后接受，创建者不会自动成为负责人。','Review accepts example.test addresses only. The nominee must verify and accept; the creator does not become an owner.') }}</small></label></div><p v-if="validation" class="full-error-text" role="alert">{{ validation }}</p><div class="full-actions"><ElButton @click="s.go('tenants')">{{ l('返回列表','Back to list') }}</ElButton><ElButton type="primary" data-primary :disabled="s.blocked" @click="create">{{ l('核对创建信息','Review organization details') }}</ElButton></div></section>
    <section v-else-if="s.page.id==='tenant'&&target" class="full-card"><h2>{{ target?.name }}</h2><dl class="full-facts"><dt>{{ l('唯一标识','Unique code') }}</dt><dd>{{ target?.code }}</dd><dt>{{ l('指定负责人','Nominated owner') }}</dt><dd>{{ target?.owner }}</dd><dt>{{ l('当前状态','Current status') }}</dt><dd>{{ s.scene==='pending_owner'||target?.state==='pending_owner'?l('等待受邀负责人验证并加入','Awaiting owner verification and acceptance'):l('企业正常','Organization active') }}</dd><dt>{{ l('已生效模块','Active modules') }}</dt><dd>{{ target?.modules.join(' · ') || l('尚未开通','None enabled') }}</dd></dl><p>{{ l('未开通模块时，负责人仍可处理基础企业设置，不显示虚构订阅或扣费结果。','Without business modules, owners can still manage basic organization settings. No subscription or charging is implied.') }}</p><div v-if="target.state==='pending_owner'&&!ownerInvitation" class="full-message"><h3>{{ l('首次负责人邀请已失效','Initial owner invitation is no longer valid') }}</h3><ElInput v-model="nomination.owner" :aria-label="l('重新指定负责人地址','Renew nominated owner email')" /><ElButton @click="nominate">{{ l('核对重新指定负责人','Review renewed owner nomination') }}</ElButton></div><div class="full-actions"><ElButton v-if="ownerInvitation" @click="s.openInvitation(ownerInvitation.id)">{{ l('审阅受邀负责人验证入口','Review nominated owner verification') }}</ElButton><ElButton type="primary" @click="s.go('module-grant',{target:target?.id || ''})">{{ l('配置模块开通','Configure modules') }}</ElButton><ElButton @click="s.go('tenants')">{{ l('返回企业列表','Back to organizations') }}</ElButton></div></section>
    <section v-else-if="target" class="full-card"><h2>{{ l('核对模块开通范围','Review module activation scope') }} · {{ target?.name }}</h2><p>{{ l('平台人工开通已发布模块，不涉及套餐购买、价格变更或扣费。未发布模块不可开通。','Platform operators enable published modules manually. This does not purchase a plan, change a price, or charge an account. Unpublished modules cannot be enabled.') }}</p><div class="full-form"><label>{{ l('生效方式','Activation mode') }}<ElSelect v-model="grant.mode" :aria-label="l('模块生效方式','Module activation mode')"><ElOption value="enabled" :label="l('开通或更新配置','Enable or update')" /><ElOption value="disabled" :label="l('关闭模块','Disable module')" /></ElSelect></label><label>{{ l('有效期至，留空表示不设到期日','Valid until; blank means no expiry') }}<ElInput v-model="grant.expiresAt" type="date" :aria-label="l('模块有效期','Module validity')" /></label><label>{{ l('额度，unlimited表示不设额度上限','Quota; unlimited means no cap') }}<ElInput v-model="grant.quota" :aria-label="l('模块额度','Module quota')" /></label></div><p class="full-muted">{{ l('已有审阅样例的生效配置为不限期、不设额度上限；新配置必须在确认页明确核对。关闭模块后现有菜单与角色不再允许业务访问。','Existing review fixtures have no expiry or quota cap. New settings are explicitly reviewed. Disabling a module blocks business access regardless of menus and roles.') }}</p><ElCheckboxGroup v-model="grant.modules"><div class="full-grid"><label class="full-card"><ElCheckbox value="crm">{{ l('客户管理','Customer management') }}</ElCheckbox><p>{{ l('允许企业按成员实际权限使用客户业务。','Allows customer operations under each member’s current grants.') }}</p></label><label class="full-card"><ElCheckbox value="marketing">{{ l('营销活动','Marketing') }}</ElCheckbox><p>{{ l('开通模块不自动授予成员执行活动权限。','Module activation does not grant campaign execution rights.') }}</p></label><label class="full-card"><ElCheckbox value="unpublished" disabled>{{ l('未发布模块','Unpublished module') }}</ElCheckbox><p>{{ l('当前不可开通','Not available for activation') }}</p></label></div></ElCheckboxGroup><p v-if="validation" class="full-error-text" role="alert">{{ validation }}</p><div class="full-actions"><ElButton @click="s.go('tenant',{target:target?.id || ''})">{{ l('取消配置','Cancel configuration') }}</ElButton><ElButton type="primary" data-primary :disabled="s.blocked" @click="enable">{{ l('核对开通影响','Review activation effects') }}</ElButton></div><ElTag style="margin-top:16px">{{ l('创建与生效以原操作回执分别确认','Creation and activation are confirmed from the original receipt') }}</ElTag></section>
    <section v-else class="full-state"><h2>{{ l('企业记录不可访问','Organization record unavailable') }}</h2><ElButton @click="s.go('tenants')">{{ l('返回可访问企业列表','Return to accessible organizations') }}</ElButton></section>
  </div>
</template>
